import java.util.ArrayList;
import java.util.List;

class Solution {
    public ListNode reverseBetween(ListNode head, int left, int right) {
        List<ListNode> nodes = new ArrayList<>();
        for (ListNode current = head; current != null; current = current.next) nodes.add(current);
        int first = left - 1;
        int last = right - 1;
        while (first < last) {
            ListNode temporary = nodes.get(first);
            nodes.set(first++, nodes.get(last));
            nodes.set(last--, temporary);
        }
        for (int index = 0; index + 1 < nodes.size(); index++) nodes.get(index).next = nodes.get(index + 1);
        nodes.get(nodes.size() - 1).next = null;
        return nodes.get(0);
    }
}

