class Solution {
    public ListNode reverseBetween(ListNode head, int left, int right) {
        ListNode dummy = new ListNode(0, head);
        ListNode before = dummy;
        for (int position = 1; position < left; position++) before = before.next;
        ListNode segmentTail = before.next;
        for (int count = 0; count < right - left; count++) {
            ListNode moving = segmentTail.next;
            segmentTail.next = moving.next;
            moving.next = before.next;
            before.next = moving;
        }
        return dummy.next;
    }
}
